#include <stdexcept>
namespace ks{namespace{GlobalTablePartialTest partialTest=nullptr;using S=GlobalTableTask::Stage;struct Point{unsigned location,length;};Point point(const GlobalTableTask&t){switch(t.stage()){case S::ReadSelector:return {0x9a50,8};case S::CompareSelector:return {0x9a58,2};case S::AdmitSelector:return {0x9a5a,2};case S::ClampSelector:return {0x9a5c,2};case S::SetStride:return {0x9a5e,2};case S::LocateRow:return {0x9a60,2};case S::ClearUpper:return {0x9a62,2};case S::BindSource:return {0x9a64,6};case S::BindDestination:return {0x9a6a,6};case S::SetRemaining:return {0x9a70,4};case S::ReadWord:return {0x9a74,2};case S::WriteWord:return {0x9a76,2};case S::TickDestination:return {0x9a78,2};case S::TickRemaining:return {0x9a7a,2};case S::AdmitRemaining:return {0x9a7c,2};case S::Complete:return {0x9a7e,8};}throw std::runtime_error("Invalid native global table stage");}}
bool GlobalTableCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0x9a50){if(selected)throw std::runtime_error("Overlapping native global table caller");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Native global table capacity exceeded");selected->emplace(h.getSP());++started;}
 if(!selected||point((*selected)->task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&task=(**selected).task;auto&v=h.regs;auto stage=task.stage();auto before=h.cycles;Boundary f(h,pc,point(task).length);auto cost=task.nextClocks();if(task.advanceBefore(cost,[&](bool selector)->uint32_t{return selector?uint8_t(h.read8(int32_t(uint32_t(v[6].er)+217))):uint16_t(h.read16(0x15282+task.rowOffset()+2*task.index()));},[&](uint16_t word){f.store16(0x17546+2*task.index(),int16_t(word));})!=cost)throw std::runtime_error("Native global table admission mismatch");switch(stage){case S::ReadSelector:f.move(v[0].rl,task.selector());break;case S::CompareSelector:h.sub8(v[0].rl,5);break;case S::ClampSelector:f.move(v[0].rl,5);break;case S::SetStride:f.move(v[0].rh,20);break;case S::LocateRow:v[0].r=int16_t(task.rowOffset());h.clockI(12);break;case S::ClearUpper:v[0].er&=65535;value(h,v[0].er);break;case S::BindSource:v[0].er=h.add32(v[0].er,0x15282);break;case S::BindDestination:f.move(v[1].er,0x17546);break;case S::SetRemaining:f.move(v[2].e,10);break;case S::ReadWord:f.move(v[2].r,task.word());v[0].er+=2;h.clockI(2);break;case S::TickDestination:f.inc(v[1].er,2);break;case S::TickRemaining:f.inc(v[2].e,-1);break;default:break;}
 if(h.cycles-before!=cost)throw std::runtime_error("Native global table clocks differ");h.pc=h.makepc(point(task).location);if(task.stage()==S::Complete){selected->reset();++completed;}return true;}
}

